import { begin, recordPoll, reset, type CheckState } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}
function typeError(fn: () => unknown): void {
  try {
    fn();
  } catch (error) {
    if (error instanceof TypeError) return;
    throw new Error('expected TypeError');
  }
  throw new Error('expected TypeError');
}

const ready: CheckState = { phase: 'ready' };
const waiting = begin(ready, '  session-1  ');
equal(waiting, { phase: 'waiting', sessionId: 'session-1', polls: 0 }, 'begin from ready');
assert(waiting !== ready, 'begin returns a new object');
typeError(() => begin(ready, '   \t'));

const retry: CheckState = { phase: 'retry', sessionId: 'old', polls: 4, reason: 'declined' };
equal(begin(retry, 'next'), { phase: 'waiting', sessionId: 'next', polls: 0 }, 'begin from retry');
const accepted: CheckState = { phase: 'accepted', sessionId: 'done', polls: 3 };
const refusedBegin = begin(accepted, 'new');
equal(refusedBegin, accepted, 'cannot begin from accepted');
assert(refusedBegin !== accepted, 'refused begin returns fresh state');

const active: CheckState = { phase: 'waiting', sessionId: 'session-1', polls: 0 };
const activeSnapshot = JSON.stringify(active);
const pending = recordPoll(active, 'session-1', 'pending');
equal(pending, { phase: 'waiting', sessionId: 'session-1', polls: 1 }, 'pending increments polls');
assert(pending !== active, 'pending returns fresh state');
const approved = recordPoll(pending, 'session-1', 'approved');
equal(approved, { phase: 'accepted', sessionId: 'session-1', polls: 2 }, 'approved increments and accepts');
const declined = recordPoll(active, 'session-1', 'declined');
equal(declined, { phase: 'retry', sessionId: 'session-1', polls: 1, reason: 'declined' }, 'declined result');
const resubmit = recordPoll(active, 'session-1', 'resubmit');
equal(resubmit, { phase: 'retry', sessionId: 'session-1', polls: 1, reason: 'resubmit' }, 'resubmit result');
assert(JSON.stringify(active) === activeSnapshot, 'polling must not mutate input');

const mismatch = recordPoll(active, ' session-1 ', 'approved');
equal(mismatch, active, 'session matching is exact');
assert(mismatch !== active, 'mismatch returns a fresh copy');
const outside = recordPoll(accepted, 'done', 'pending');
equal(outside, accepted, 'poll outside waiting is unchanged');
assert(outside !== accepted, 'outside poll returns a fresh copy');

const resetResult = reset(retry);
equal(resetResult, { phase: 'ready' }, 'reset result');
assert(resetResult !== retry, 'reset returns a new object');

